// -----------------------------------------------------------------------------
// Journey Booking — Complete Request DTO
// -----------------------------------------------------------------------------

import { ApiPropertyOptional } from '@nestjs/swagger';
import { IsDateString, IsOptional } from 'class-validator';

/**
 * Optional request payload for completing a Journey Booking.
 *
 * The booking public ID is supplied through the route parameter.
 * The correlation ID is generated by the controller.
 * The completion timestamp is optional.
 */
export class CompleteJourneyBookingDto {
  @ApiPropertyOptional({
    description:
      'Explicit completion timestamp. When omitted, the application uses the current time.',
    example: '2026-08-18T16:30:00.000Z',
    format: 'date-time',
  })
  @IsOptional()
  @IsDateString()
  completedAt?: string;
}

export default CompleteJourneyBookingDto;
